G2=[[16200,39344,29765],[23609,12876,45306],[19381,50319,38408]]
def is_sc(G,r,c):
    v=G[r][c]
    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
        rr,cc=r+dr,c+dc
        if 0<=rr<3 and 0<=cc<3 and G[rr][cc]>=v: return False
    return True
for gi,(G,x0) in enumerate([(G1,40),(G2,480)]):
    for r in range(3):
        for c in range(3):
            RECT(f"gd{gi}c{r}{c}",x0+c*125,160+r*70,125,70,"#C8E6C9" if is_sc(G,r,c) else "#FFFFFF","#16253F",3)
            L(f"{G[r][c]:,}",f"gd{gi}t{r}{c}",y=203+r*70,s=20,x=x0+c*125+62)
